import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner res = new Scanner(System.in);
        int a = res.nextInt();
        int t = res.nextInt();

        System.out.println(gcd(a,t));
    }

    public static int gcd(int a, int t) {
        int out = a % t;
        if (out == 0) {
            return t;
        }
        return gcd(t, out);
    }
}

