			int ans3 = Integer.parseInt(cnt.next());
			int t = Integer.parseInt(cnt.next());
			int ans =Divisor(ans3,t);
			System.out.println(ans);
		}
	}
	public static int Divisor(int ans3, int t){
		int digit=Math.max(ans3, t);
		int re=Math.min(ans3, t);

		if(digit%re==0){
			return re;
		}else{
			return Divisor(digit%re,re);
		}
	}
}

