import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner strb = new Scanner(System.in);
        String prospectMin = strb.next();
        String t = strb.next();

        int ta = Integer.parseInt(prospectMin);
        int message = Integer.parseInt(t);

        int answer = divisor(ta, message);

        System.out.println(answer);
        strb.close();
    }

    static int divisor(int ta, int message) {
        if (message > ta) {
            return divisor(message, ta);
        }
        while (message != 0) {
            int min = ta % message;
            ta = message;
            message = min;
        }
        return ta;
    }
}

