    public static void input(Integer[] ary1){
        int r = ary1.length;
        for(int costs = 0; costs < r - 1; costs++){ System.out.print(ary1[costs] + " "); }
        System.out.println(ary1[r - 1]);
    }
    public static Integer[] output(BufferedReader arrStr) throws IOException
    {
        String[] numbers = arrStr.readLine().split(" ");
        int r = numbers.length;
        Integer[] ary1 = new Integer[r];
        for(int costs = 0; costs < r; costs++){ ary1[costs] = Integer.parseInt(numbers[costs]); }
        return ary1;
    }
}

