import java.util.Scanner;
import java.util.regex.Pattern;
import java.util.regex.Matcher;
public class Main {
	public static void main( String[] args ) {
		int[] index = new int[2];
		Scanner scan = new Scanner( System.in ) ;
		String ss = scan.nextLine() ;
		rotate( ss, index ) ;
		while( index[0] != 0 || index[1] != 0 ) {
			if ( index[0] > index[1] ) {
				System.out.println( index[1] + " " + index[0] ) ;
			} else {
				System.out.println( index[0] + " " + index[1] ) ;
			}
			ss = scan.nextLine();
			rotate( ss, index ) ;
		}
	}
	public static void rotate( String string, int[] index ) {
		Pattern sum = Pattern.compile( "([0-9]+)\\s+([0-9]+)");
		Matcher ch = sum.matcher( string ) ;
		if ( ch.find() == true ) {
			index[0] = Integer.parseInt( ch.group(1) ) ;
			index[1] = Integer.parseInt( ch.group(2) ) ;
		}
	}
}

