public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    Scanner st = new Scanner(System.in);

    void input() {
        String arr;
        while (true) {
            arr = st.nextLine();
            String[] s = arr.split(" ");
            int now = Integer.parseInt(s[0]);
            int max = Integer.parseInt(s[1]);
            if (selectionSort(now, max)) break;
            System.out.println(find(now, max));
        }
    }

    int find(int now, int max) {
        int dist = 0;
        for (int costMinus = 1; costMinus <= now; ++costMinus) {
            for (int processQueue = costMinus + 1; processQueue <= now; ++processQueue) {
                if (costMinus == processQueue) continue;
                int list = max - costMinus - processQueue;
                if (costMinus == list || processQueue == list) continue;
                if (processQueue < list && list <= now) {
                    dist++;
                }
            }
        }
        return dist;
    }

    boolean selectionSort(int now, int max) {
        return now == 0 && max == 0;
    }

}

