	    int r = cin.nextInt();
	    int max = cin.nextInt();
	    if (r == 0 && max == 0) {
		break;
	    }
	    for (int cost = 1; cost < r - 1; cost++) {
		if (cost > max) {
		    break;
		}
		for (int size = cost + 1; size < r; size++) {
		    if (size + cost > max) {
			break;
		    }
		    for (int correct = size + 1; correct < r + 1; correct++) {
			if (size + cost + correct > max) {
			    break;
			}
			if (size + cost + correct == max) {
			    cnt++;
			    break;
			}
		    }
		}
	    }
	    System.out.println(cnt);
	}
    }
}

