import java.util.Scanner;

public class Main {

    /*
     * 行列の積
     * 
     * n×m の行列 A と m×l の行列 B を入力し、それらの積である n×l の行列 C を出力するプログラムを作成してください。行列 C
     * の各要素 cij は次の式で得られます：
     * 
     * cij=?k=1maikbkj ここで、A、B、C の各要素をそれぞれ aij、bij、cij とします。
     * 
     * Input １行目に n、m、l が空白区切りで与えられます。
     * 
     * 続く行に n×m の行列 A と m×l の行列 B が与えられます。
     * 
     * Output n×l の行列 C の要素 cij を出力してください。各行の隣り合う要素を１つの空白で区切ってください。
     * 
     * Constraints 1?n,m,l?100 0?aij,bij?10000
     */
    public static void main(String[] args) {

        Scanner c = new Scanner(System.in);

        int intLine = c.nextInt();
        int count = c.nextInt();
        int fact = c.nextInt();

        int[][] area = new int[intLine][count];
        int[][] array2 = new int[count][fact];

        for (int input1 = 0; input1 < area.length; input1++) {
            for (int sum = 0; sum < area[input1].length; sum++) {
                area[input1][sum] = c.nextInt();
            }
        }

        for (int input1 = 0; input1 < array2.length; input1++) {
            for (int sum = 0; sum < array2[input1].length; sum++) {
                array2[input1][sum] = c.nextInt();
            }
        }

        c.close();
        long[][] array3 = new long[intLine][fact];

        for (int input1 = 0; input1 < intLine; input1++) {
            for (int sum = 0; sum < fact; sum++) {
                for (int str1 = 0; str1 < count; str1++) {
                    array3[input1][sum] += area[input1][str1]*array2[str1][sum];
                }
            }
        }

        for (int input1 = 0; input1 < array3.length; input1++) {
            for (int sum = 0; sum < array3[input1].length; sum++) {
                System.out.print(array3[input1][sum]);
                if(sum != fact -1){
                    System.out.print(" ");
                }
            }
            System.out.println();
        }
    }

}

