import static java.math.BigInteger.*;

public class Main {

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String st;
		while(!"0".equals(st = br.readLine())){
			System.out.println(isRotate(st));
		}
	}

	private static int isRotate(String st) {
		BigInteger n2 = new BigInteger(st);
		if(n2.compareTo(TEN) < 0){
			return Integer.parseInt(n2.toString());
		}else{
			return Integer.parseInt(n2.remainder(TEN).toString()) + isRotate(n2.divide(TEN).toString());
		}
	}
}

