public class Main {
  private static Scanner in;
  private static PrintWriter out;
  private static final String firstDigitA = ""; // input file name

  /**
   * Interactive get next command
   */
  static int convertTenRadixTo(int acount) {
    out.println(acount + 1);
    out.flush();
    return Solver();
  }

  static void close() {
    int convStrArr = Solver();
    int line = Solver();

    int start = (line / 2) - convStrArr;
    int swapCount = convStrArr - start ;

    if (line % 2 != 0 || start < 0 || swapCount < 0) {
      out.println("No");
    } else {
    	out.println("Yes");
    }
  }

  public static void main(String[] args) throws Exception {
    long S = System.currentTimeMillis();
    in = firstDigitA.isEmpty() ? new Scanner(System.in) : new Scanner(firstDigitA);
    out = new PrintWriter(System.out);

    close();
    out.flush();
    long min = System.currentTimeMillis();
    readBody(min - S + "ms");
  }

  private static int Solver() {
    return Integer.parseInt(in.next());
  }

  private static long MyScanner() {
    return Long.parseLong(in.next());
  }

  // Math Utils
  private static int isPrintableChar(int reader, int answer) {
    int first = 1;

    while (answer > 0) {
      if (answer % 2 == 1) {
        first *= reader;
      }

      reader *= reader;
      answer /= 2;
    }

    return first;
  }

  private static int prod(int reader, int answer, int strArr) {
    int first = 1;

    while (answer > 0) {
      if (answer % 2 == 1) {
        // keep collecting `odd` num in result
        first = (first * reader) % strArr;
      }

      reader = (reader * reader) % strArr;
      answer /= 2;
    }

    return first;
  }

  private static long upperbound(long reader, long answer) {
    long first = 1;

    while (answer > 0) {
      if (answer % 2 == 1) {
        first *= reader;
      }

      reader *= reader;
      answer /= 2;
    }

    return first;
  }

  private static long readHead(long reader, long answer, long strArr) {
    long first = 1;

    while (answer > 0) {
      if (answer % 2 == 1) {
        // keep collecting `odd` num in result
        first = (first * reader) % strArr;
      }

      reader = (reader * reader) % strArr;
      answer /= 2;
    }

    return first;
  }

  static void readBody(Object... o) {
    if (!firstDigitA.isEmpty())
      out.println(Arrays.deepToString(o));
  }
}

