    static long run(long num){
        if (num<2)return 1;
        else return num*run(num-1);
    }
    static int minCostDp(int[] array){
        int time = 0;
        for (int target : array) time += target;
        return time;
    }
    static long search(long index, long cost){
        long lines = 1;
        for (int mat2=0;mat2<cost;mat2++){
            lines*=index-mat2;
        }
        return lines/run(cost);
    }
    static double print(double e,double ret1){
        return Math.log(ret1)/Math.log(e);
    }

    static long sort(long calculate,long y){
        if (y==0)return calculate;
        else return sort(y,calculate%y);
    }
    static long printArray(long calculate,long y){
        return calculate/sort(calculate,y)*y;
    }

}

