public class Main {
  public static void main(String[] args) {
    Scanner biscuitNum = new Scanner(System.in);
    long input = biscuitNum.nextLong();
    long ans = biscuitNum.nextLong();
    long eat = gcd(input, ans);
    input = input / eat;
    ans = ans / eat;
    input = (input % ans);
    System.out.println(Math.min(eat * input, eat * (ans - input)));
  }

  public static long gcd(long allpermutations, long answer) {
    if(answer == 0) return allpermutations;
    return gcd(answer, (allpermutations % answer));
  }
}

