        Scanner scan=new Scanner(System.in);
        int ng=scan.nextInt();
        PriorityQueue<String> ss=new PriorityQueue<String>();
        Queue<String> dist=new ArrayDeque<String>();
        for(int input2=0;input2<ng;input2++){
            ss.add(scan.next());
        }
        int count=0;
        while(ss.peek()!=null){
            String st=ss.peek();
            int input2=0;
            for(;ss.peek()!=null&&ss.peek().equals(st);input2++){
                ss.remove();
            }
            if(count==input2){
                dist.add(st);
            }else if(count<input2){
                count=input2;
                dist.clear();
                dist.add(st);
            }
        }
        while(dist.peek()!=null){
            System.out.println(dist.remove());
        }
    }
}

