import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner list = new FastScanner();
        final int j = list.nextInt();
        final int random = list.nextInt();
        int time[] = list.nextIntArray(random);
        int counter = 0;
        for (int ints = 0; ints < random; ints++)
            counter += time[ints];
        if (counter < j)
            System.out.println("No");
        else
            System.out.println("Yes");
    }

    // FastScanner start
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] writer = new byte[1024];
        private int builder = 0;
        private int bufPointer = 0;

        private boolean nextString() {
            if (builder < bufPointer) {
                return true;
            } else {
                builder = 0;
                try {
                    bufPointer = in.read(writer);
                } catch (IOException inputLine) {
                    inputLine.printStackTrace();
                }
                if (bufPointer <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readLineChar() {
            if (nextString())
                return writer[builder++];
            else
                return -1;
        }

        private static boolean readLine(int copy) {
            return 33 <= copy && copy <= 126;
        }

        public boolean nextStrings() {
            while (nextString() && !readLine(writer[builder]))
                builder++;
            return nextString();
        }

        public String nextIntMap() {
            if (!nextStrings())
                throw new NoSuchElementException();
            StringBuilder ss = new StringBuilder();
            int start = readLineChar();
            while (readLine(start)) {
                ss.appendCodePoint(start);
                start = readLineChar();
            }
            return ss.toString();
        }

        public long nextLong() {
            if (!nextStrings())
                throw new NoSuchElementException();
            long num = 0;
            boolean stringBuilder = false;
            int start = readLineChar();
            if (start == '-') {
                stringBuilder = true;
                start = readLineChar();
            }
            if (start < '0' || '9' < start) {
                throw new NumberFormatException();
            }
            while (true) {
                if ('0' <= start && start <= '9') {
                    num *= 10;
                    num += start - '0';
                } else if (start == -1 || !readLine(start)) {
                    return stringBuilder ? -num : num;
                } else {
                    throw new NumberFormatException();
                }
                start = readLineChar();
            }
        }

        public int nextLongs() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
                throw new NumberFormatException();
            return (int) nl;
        }

        public double nextStr() {
            return Double.parseDouble(nextIntMap());
        }

        public int[] nextIntArray(int num) {
            int splitString[] = new int[num];
            for (int ints = 0; ints < num; ints++) {
                splitString[ints] = nextLongs();
            }
            return splitString;
        }
    }
    // FastScanner end
}

