import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {
	public static void main(String[] args) {
		Scanner stack = new Scanner(System.in);
		int set = stack.nextInt();
		long Times = stack.nextLong();
		int sumA = stack.nextInt();
		int age[] = new int[sumA];

		TreeMap<Integer, Integer> count = new TreeMap<Integer, Integer>();

		for (int input = 0; input < age.length; input++) {
			age[input] = stack.nextInt();

			if (count.containsKey(age[input])) {
				count.put(age[input], count.get(age[input])+1);
			} else {
				count.put(age[input], 1);
			}
		}

		if (Times>sumA) {
			for (int input = 0; input < set; input++) {
				System.out.println("Yes");
			}
			return;
		}

		long ret = sumA-Times + 1;

		Map<Integer, Integer> times = new HashMap<>();

		for(Map.Entry<Integer, Integer> line : count.entrySet()) {
			if (line.getValue() >= ret) {
				times.put(line.getKey(), 1);
			}
		}

		for (int input = 1; input < set + 1; input++) {
			if (times.containsKey(input)) {
				System.out.println("Yes");
			} else {
				System.out.println("No");
			}
		}
	}
}

