public class Main {

	public static void main(String[] args) {
		Scanner ary_input = new Scanner(System.in);
		int item = ary_input.nextInt(); //参加者
		int t = ary_input.nextInt(); //ポイント
		int num = ary_input.nextInt(); //クイズの回数
		int insBR[] =  new int[num]; //正解者
		for(int intVector=0;intVector<num;intVector++) {
			insBR[intVector] = ary_input.nextInt();
		}

		int prime[] = new int[item];
		//初期化
		for (int state :prime ) {
			state=0;
		}

		//自分以外に、K回正解されるとアウト。
		//したがって正解数Q回ならば、自分の正解数をAとすると、Q-A<Kならいい。つまり、A＞Q-Kなら良い。
		//開始０ポイントで、正解した人は１ポイントとし、
		//終了までにQ-Kポイントよりも獲得（Q-Kはだめ）すると突破に読み換える。
		for(int intVector=0;intVector<num;intVector++) {
			prime[insBR[intVector]-1]++;
		}

		StringBuilder intColumnSum = new StringBuilder();
		for (int state :prime ) {
			if(state>num-t) {
				intColumnSum.append("Yes");
				intColumnSum.append(System.getProperty("line.separator"));
			}else {
				intColumnSum.append("No");
				intColumnSum.append(System.getProperty("line.separator"));
			}
		}
		String colNum = intColumnSum.toString();

		System.out.println(colNum);


	}
}

