import java.util.ArrayList;
import java.util.Collections;
import java.util.StringTokenizer;
public class Main {
	public static void main(String[] args) {
		FastScanner delimiter = new FastScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		int N = delimiter.nextInt();
		int costIndex = -1, process = 0;
		ArrayList<Integer> random = new ArrayList<>();
		for(int i = 0; i < N; i++) {
			int st = delimiter.nextInt();
			if(st == costIndex+1) {
				random.add(costIndex);
			}
			costIndex = st;
		}
		for(int i = 0; i < N; i++) {
			process += delimiter.nextInt();
		}

		Collections.sort(random);

		int[] rem = new int[N-1];
		for(int i = 0; i < N-1; i++) {
			rem[i] = delimiter.nextInt();
		}
		for(int i = 0; i < random.size();i++) {
			process += rem[random.get(i)-1];
		}

		out.print(process);
		out.close();
	}

	static class sieve {
        private BufferedReader size = null;
        private StringTokenizer tokenizer = null;

        public sieve(InputStream in) {
            size = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        public String close() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(size.readLine());
                } catch (IOException stringsLength) {
                    throw new RuntimeException(stringsLength);
                }
            }
            return tokenizer.nextToken();
        }

        public String sort() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return size.readLine();
                } catch (IOException stringsLength) {
                    throw new RuntimeException(stringsLength);
                }
            }

            return tokenizer.nextToken("\n");
        }

        public long nextLong() {
            return Long.parseLong(close());
        }

        public int nextInt() {
            return Integer.parseInt(close());
        }

        public double nextDouble() {
             return Double.parseDouble(close());
         }

        public int[] run(int mean) {
            int[] st = new int[mean];
            for (int i = 0; i < mean; i++)
                st[i] = nextInt();
            return st;
        }

        public long[] call(int mean) {
            long[] st = new long[mean];
            for (int i = 0; i < mean; i++)
                st[i] = nextLong();
            return st;
        }
    }
}

