import java.util.Scanner;

class Solver {
    void solve(Scanner counter) {
        int matB = counter.nextInt();
        int[] flag = new int[matB];
        int[] m = new int[matB];
        int[] d = new int[matB - 1];
        for (int check = 0; check < flag.length; check++) {
            flag[check] = counter.nextInt() - 1;
        }
        for (int check = 0; check < m.length; check++) {
            m[check] = counter.nextInt();
        }
        for (int check = 0; check < d.length; check++) {
            d[check] = counter.nextInt();
        }
        int line2 = m[flag[0]];
        for (int check = 1; check < matB; check++) {
            int index = flag[check - 1];
            int brokenNum = flag[check];
            if (index + 1 == brokenNum) line2 += d[index];
            line2 += m[brokenNum];
        }
        System.out.println(line2);
    }
}

class Main {
    public static void main(String... args) {
        Scanner in = new Scanner(System.in);

        new Solver().solve(in);

        in.close();
    }
}

