import java.util.InputMismatchException;
import java.io.IOException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream remainder = System.in;
        OutputStream tokenizer = System.out;
        FastReader in = new FastReader(remainder);
        PrintWriter bufPointer = new PrintWriter(tokenizer);
        AX str = new AX();
        str.solve(1, in, bufPointer);
        bufPointer.close();
    }

    static class AX {
        public void readLine(int substring, FastReader list, PrintWriter bufPointer) {
            int second = list.nextInt();
            int time = list.nextInt();
            bufPointer.println(Math.max(second + time, Math.max(second * time, second - time)));
        }

    }

    static class nextStringArray {
        private InputStream stream;
        private byte[] prime = new byte[1024];
        private int splitString;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public nextStringArray(InputStream stream) {
            this.stream = stream;
        }

        public int printLine() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (splitString >= numChars) {
                splitString = 0;
                try {
                    numChars = stream.read(prime);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return prime[splitString++];
        }

        public int nextDoubleArray() {
            int change = printLine();
            while (fillBuffer(change)) {
                change = printLine();
            }
            int size = 1;
            if (change == '-') {
                size = -1;
                change = printLine();
            }
            int res = 0;
            do {
                if (change < '0' || change > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += change - '0';
                change = printLine();
            } while (!fillBuffer(change));
            return res * size;
        }

        public boolean fillBuffer(int change) {
            if (filter != null) {
                return filter.isSpaceChar(change);
            }
            return isWhitespace(change);
        }

        public static boolean isWhitespace(int change) {
            return change == ' ' || change == '\n' || change == '\r' || change == '\t' || change == -1;
        }

        public interface SpaceCharFilter {
            public boolean fillBuffer(int min);

        }

    }
}

