// https://qiita.com/p_shiki37/items/a0f6aac33bf60f5f65e4
class FastScanner {

    private final InputStream in = System.in;
    private final byte[] remainder = new byte[1024];
    private int ptr = 0;
    private int counter = 0;

    private boolean nextDoubleMap() {
        if (ptr < counter) {
            return true;
        } else {
            ptr = 0;
            try {
                counter = in.read(remainder);
            } catch (IOException str) {
                str.printStackTrace();
            }
            if (counter <= 0) {
                return false;
            }
        }
        return true;
    }

    private int FastScanner() {
        if (nextDoubleMap()) {
            return remainder[ptr++];
        } else {
            return -1;
        }
    }

    private static boolean readHead(int c21) {
        return 33 <= c21 && c21 <= 126;
    }

    public boolean hasNext() {
        while (nextDoubleMap() && !readHead(remainder[ptr])) {
            ptr++;
        }
        return nextDoubleMap();
    }

    public String nextStrings() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        StringBuilder process = new StringBuilder();
        int strArr = FastScanner();
        while (readHead(strArr)) {
            process.appendCodePoint(strArr);
            strArr = FastScanner();
        }
        return process.toString();
    }

    public long nextLong() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        long debugDataPath = 0;
        boolean minus = false;
        int strArr = FastScanner();
        if (strArr == '-') {
            minus = true;
            strArr = FastScanner();
        }
        if (strArr < '0' || '9' < strArr) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= strArr && strArr <= '9') {
                debugDataPath *= 10;
                debugDataPath += strArr - '0';
            } else if (strArr == -1 || !readHead(strArr)) {
                return minus ? -debugDataPath : debugDataPath;
            } else {
                throw new NumberFormatException();
            }
            strArr = FastScanner();
        }
    }

    public int nextInt() {
        long numChars = nextLong();
        if (numChars < Integer.MIN_VALUE || numChars > Integer.MAX_VALUE) {
            throw new NumberFormatException();
        }
        return (int) numChars;
    }

    public double nextDouble() {
        return Double.parseDouble(nextStrings());
    }
}

