class FastScanner {
	private final InputStream in = System.in;
	private final byte[] reader = new byte[1024];
	private int writer = 0;
	private int builder = 0;

	private boolean nextChar() {
		if (writer < builder) {
			return true;
		} else {
			writer = 0;
			try {
				builder = in.read(reader);
			} catch (IOException newProcess) {
				newProcess.printStackTrace();
			}
			if (builder <= 0) {
				return false;
			}
		}
		return true;
	}

	private int readLine() {
		if (nextChar())
			return reader[writer++];
		else
			return -1;
	}

	private static boolean read(int c22) {
		return 33 <= c22 && c22 <= 126;
	}

	public boolean nextStr() {
		while (nextChar() && !read(reader[writer]))
			writer++;
		return nextChar();
	}

	public String nextLongs() {
		if (!nextStr())
			throw new NoSuchElementException();
		StringBuilder divisors = new StringBuilder();
		int array = readLine();
		while (read(array)) {
			divisors.appendCodePoint(array);
			array = readLine();
		}
		return divisors.toString();
	}

	public long nextInts() {
		if (!nextStr())
			throw new NoSuchElementException();
		long nh = 0;
		boolean counter = false;
		int array = readLine();
		if (array == '-') {
			counter = true;
			array = readLine();
		}
		if (array < '0' || '9' < array) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= array && array <= '9') {
				nh *= 10;
				nh += array - '0';
			} else if (array == -1 || !read(array)) {
				return counter ? -nh : nh;
			} else {
				throw new NumberFormatException();
			}
			array = readLine();
		}
	}

	public int nextInt() {
		long nl = nextInts();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
			throw new NumberFormatException();
		return (int) nl;
	}

	public double nextArray() {
		return Double.parseDouble(nextLongs());
	}
}

