import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream stream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(stream);
        PrintWriter min_number = new PrintWriter(outputStream);
        B reader = new B();
        reader.solve(1, in, min_number);
        min_number.close();
    }

    static class B {
        public void Solver(int testNumber, Scanner in, PrintWriter min_number) {
            // 入力
            int ns = Integer.parseInt(in.next());
            int datasets = Integer.parseInt(in.next());
            int curEnd[] = new int[ns];
            for (int index = 0; index < ns; index++) {
                curEnd[index] = Integer.parseInt(in.next());
            }

            int bounds[] = new int[ns + 1];
            bounds[0] = 0;
            for (int index = 1; index <= ns; index++) {
                bounds[index] = bounds[index - 1] + curEnd[index - 1];
            }
            int min = 0;
            for (int index = 0; index <= ns; index++) {
                if (bounds[index] <= datasets) ++min;
            }

            // 出力
            min_number.println(min);

        }

    }
}

