                    res = -1;
                    arr_b = start.read();
                } else if (arr_b == '+') {
                    arr_b = start.read();
                }
                double arr = arr_b - '0';
                while (true) {
                    arr_b = start.read();
                    if (arr_b < '0' || '9' < arr_b) break;
                    arr *= 10;
                    arr += arr_b - '0';
                }
                if (arr_b != '.') return res * arr;
