public class Main {
    public static void main(String[] args) {
        final Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        final int e = in.nextInt();
        final int t = in.nextInt();
        final Set<Integer> before = new HashSet<>();
        for (int value = 0; value < t; value++) {
            before.add(in.nextInt());
        }

        int[] swapCount = new int[e + 1];

        swapCount[0] = 1;
        for (int value = 1; value <= e; value++) {
            if (before.contains(value)) {
                continue;
            }
            int Member_Point = 0;
            if (!before.contains(value - 1)) {
                Member_Point += swapCount[value - 1];
            }
            if (value - 2 >= 0 && !before.contains(value - 2)) {
                Member_Point += swapCount[value - 2];
            }
            Member_Point %= 1_000_000_007;
            swapCount[value] = Member_Point;
        }
        System.out.println(swapCount[e]);
    }
}

