public class Main {

	static Scanner bufferPointer;
	static long[][] minNum;
    static int index2=1;
	public static void main(String[] args) {
	    bufferPointer = new Scanner(System.in);

	    int nums=gi();
	    int cost=gi();
        boolean[] cant=new boolean[nums+1];
        int[] acd=new int[cost];
        minNum=new long[2][nums+1];
        minNum[0][1]=1;
        minNum[1][1]=1;
        cant[0]=true;
        cant[nums]=true;

        for (int input=0; input<cost;input++) {
            acd[input]=gi();
            cant[acd[input]]=true;
            cant[acd[input]-1]=true;
            cant[acd[input]+1]=true;
            if(input!=0 && acd[input]-acd[input-1] == 1) {
            	System.out.println(0);
            	return;
            }
        }

        long c=0;
        List<Long> card = new ArrayList<Long>();
        for (int input=0; input<nums+1;input++) {
            if(c!=0 && cant[input]) {
            	card.add(c);
            	c=0;
            } else if(!cant[input]) {
            	c++;
            }
        }

        long costs=1;
        for (int input=0; input<card.size();input++) {
        	long strs=card.get(input);
        	costs = (costs*gv(strs)) % 1000000007l;
        }

        System.out.println(costs);
	}

	public static long gv(long trueUseNum) {
		if(index2>=trueUseNum) {
			return (minNum[0][(int)trueUseNum]+minNum[1][(int)trueUseNum]) % 1000000007l;
		}

		for (int input=index2+1; input<=trueUseNum; input++) {
			minNum[0][input]=minNum[1][input-1];
			minNum[1][input]=(minNum[0][input-1] +minNum[1][input-1]) % 1000000007l;
		}
		index2=(int)trueUseNum;
		return (minNum[0][(int)trueUseNum]+minNum[1][(int)trueUseNum]) % 1000000007l;
	}

	// a^nをmodで割ったあまり
	public static long binarySearchRightMost(long acd, long nums, long current) {
		long result=1;
		while(nums>0) {
			if((nums & 1) == 1) result=result*acd%current;
			acd=acd*acd%current;
			nums=nums>>1;
		}

		return result;
	}

	// 文字列として入力を取得
	public static String gcd() {
		return bufferPointer.next();
	}

	// intとして入力を取得
	public static int gi() {
		return Integer.parseInt(bufferPointer.next());
	}

	// longとして入力を取得
	public static long gl() {
		return Long.parseLong(bufferPointer.next());
	}

	// doubleとして入力を取得
	public static double gd() {
		return Double.parseDouble(bufferPointer.next());
	}
}

