import java.math.BigInteger;
import java.util.Scanner;

public class distance {
	Integer string[];
	BigInteger numbers[];

	public distance(int num, Integer arg[]) {
		string = new Integer[num];
		numbers = new BigInteger[num];
		for (int it = 0; it < string.length; it++) {
			string[it] = 1;
		}
		for (int reader : arg) {
			string[reader] = 0;
		}

	}

	public static void main(String[] args) {
		Scanner st = new Scanner(System.in);
		int num = st.nextInt();
		int dist = st.nextInt();
		Integer arg[] = new Integer[dist];
		for (int it = 0; it < dist; it++) {
			arg[it] = st.nextInt();
		}
		System.out.println(
				new Main(num, arg).calc(0).mod(new BigInteger("1000000007")));
	}

	public BigInteger count(int current) {
		BigInteger ret = numbers[current];
		BigInteger result;
		if (ret != null) {
			return ret;
		}
		if (current >= string.length) {
			result = BigInteger.ZERO;
		} else if (current == string.length - 1) {
			result = BigInteger.ONE;
		} else if (current == string.length - 2) {
			result = BigInteger.ONE
					.add(((string[current + 1] == 1) ? BigInteger.ONE
							: BigInteger.ZERO));
		} else {
			result = ((string[current + 1] == 1) ? count(current + 1)
					: BigInteger.ZERO)
							.add((string[current + 2] == 1) ? count(current + 2)
									: BigInteger.ZERO);
		}
		numbers[current] = result;
		return result;
	}
}

