/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskC delimiter = new TaskC();
        delimiter.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        static long[] costIndexs = new long[100000 + 1];

        public void readIntsSplitByDelimiter(int bufferdReader, InputReader in, OutputWriter out) {
            Arrays.fill(costIndexs, -1);
            int cost = in.readInt();
            int processingTime = in.readInt();
            for (int debugDataPath = 0; debugDataPath < processingTime; debugDataPath++) {
                costIndexs[in.readInt()] = 0;
            }
            long requirement = strList_(cost);
            out.printLine(requirement % 1000000007);

        }

        public long strList_(int tle) {
            if (costIndexs[tle] != -1) {
                return costIndexs[tle];
            }
            if (tle == 0) {
                return 0;
            }
            if (tle == 1) {
                return 1;
            }
            if (tle == 2) {
                if (costIndexs[1] == 0) {
                    return 1;
                }
                return 2;
            }

            costIndexs[tle] = (strList_(tle - 1) + strList_(tle - 2)) % 1000000007;
            return costIndexs[tle];
        }

    }

    static class readLineByte {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int remainder;
        private int bufPointer;
        private InputReader.SpaceCharFilter filter;

        public readLineByte(InputStream stream) {
            this.stream = stream;
        }

        public int readLong() {
            if (bufPointer == -1) {
                throw new InputMismatchException();
            }
            if (remainder >= bufPointer) {
                remainder = 0;
                try {
                    bufPointer = stream.read(buf);
                } catch (IOException name) {
                    throw new InputMismatchException();
                }
                if (bufPointer <= 0) {
                    return -1;
                }
            }
            return buf[remainder++];
        }

        public int readLongsSplitByDelimiter() {
            int copy = readLong();
            while (isSpaceChar(copy)) {
                copy = readLong();
            }
            int stringsLength = 1;
            if (copy == '-') {
                stringsLength = -1;
                copy = readLong();
            }
            int res = 0;
            do {
                if (copy < '0' || copy > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += copy - '0';
                copy = readLong();
            } while (!isSpaceChar(copy));
            return res * stringsLength;
        }

        public boolean isSpaceChar(int copy) {
            if (filter != null) {
                return filter.isSpaceChar(copy);
            }
            return string(copy);
        }

        public static boolean string(int copy) {
            return copy == ' ' || copy == '\n' || copy == '\r' || copy == '\t' || copy == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int convStrList);

        }

    }

    static class OutputWriter {
        private final PrintWriter ar;

        public OutputWriter(OutputStream outputStream) {
            ar = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer ar) {
            this.writer = new PrintWriter(ar);
        }

        public void close() {
            ar.close();
        }

        public void printLine(long debugDataPath) {
            ar.println(debugDataPath);
        }

    }
}

