public class Main {

    public static void main(String[] args) throws Exception {
        try (BufferedInputStream in = new BufferedInputStream(System.in);
             PrintWriter counter = new PrintWriter(new BufferedOutputStream(System.out))) {

            Scanner scn = new Scanner(in);

            // 10:42-

            int stackCount = 1_000_000_007;
            int nums = scn.nextInt();
            int dist = scn.nextInt();
            int[] as = new int[dist];

            Set<Integer> broken = new HashSet<>();
            for (int input = 0; input < as.length; input++) broken.add(scn.nextInt());

            int[] dp = new int[nums + 1];
