class Solver {
    final Map<Long, Long> mem = new HashMap<>();

    public long Solver(long maxKachi, Set<Long> ans) {
        return combinit(0, maxKachi, ans);
    }

    private long combinit(long idxStart, long minCost, Set<Long> ans) {
        if (mem.containsKey(idxStart)) {
            return mem.get(idxStart) % Main.MOD;
        }

        if (ans.contains(idxStart) || idxStart > minCost) {
            return 0;
        }
        if (idxStart == minCost) {
            return 1;
        }

        final long dc1 = combinit(idxStart + 1, minCost, ans) % Main.MOD;
        mem.put(idxStart + 1, dc1);

        final long S2 = combinit(idxStart + 2, minCost, ans) % Main.MOD;
        mem.put(idxStart + 2, S2);

        return (dc1 + S2) % Main.MOD;
    }


}

