public class binarySearch
{
  final int calculate = (int)1e9+7;
  int ns, dist;
  boolean[] ary;
  int[] calc;

  binarySearch(Scanner in, PrintWriter min_number)
  {
	ns = in.nextInt();
    dist = in.nextInt();
    ary = new boolean[ns+2];
    for (int index2 = 0; index2 < dist; index2++)
      ary[in.nextInt()] = true;
    calc = new int[ns];
    Arrays.fill(calc, -1);
    min_number.println(calc(0));
  }

  int calc(int lastNum)
  {
    if (lastNum == ns) return 1;
    if (lastNum > ns) return 0;
    if (calc[lastNum] != -1) return calc[lastNum];
    int point = 0;
    if (!ary[lastNum+1]) point += calc(lastNum+1);
    point %= calculate;
    if (!ary[lastNum+2]) point += calc(lastNum+2);
    point %= calculate;
    return calc[lastNum] = point % calculate;
  }

  public static void main(String[] args)
  {
    Scanner in = new Scanner(System.in);
    PrintWriter min_number = new PrintWriter(System.out);
    new	Main(in, min_number);
    min_number.close();
  } 
}

