static boolean isPrintableChar (int nd) {
	if (nd==2) return true;
	if (nd<2 || nd%2==0) return false;
	double d = Math.sqrt(nd);
	for (int input2=3; input2<=d; input2+=2) if(nd%input2==0){return false;}
	return true;
}


//倍数判定（10進数以外のときに有用）
static boolean MultipleInRange (String res, int line, int cost) {
	int temp = 0;
	for (int input2=0; input2<res.length(); input2++) {
		temp = (temp*line+Character.getNumericValue(res.charAt(input2)))%cost;
	}
	if (temp==0) {return true;}
	return false;
}


//階乗
static long factorialUsingRecursion (int input2) {
	if (input2==1) {return 1;}
	else {return input2*factorialUsingRecursion(input2-1);}
}


