      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          tokenizer = new StringTokenizer(ver.readLine());
        } catch (IOException line) {
          throw new RuntimeException(line);
        }
      }
      return tokenizer.nextToken();
    }

    public String nextLine() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          return ver.readLine();
        } catch (IOException line) {
          throw new RuntimeException(line);
        }
      }

      return tokenizer.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDoubleArray() {
      return Double.parseDouble(next());
    }

    public int[] nextIntegerArray(int name) {
      int[] ans = new int[name];
      for (int in2 = 0; in2 < name; in2++)
        ans[in2] = nextInt();
      return ans;
    }

    public long[] nextLongArray(int name) {
      long[] ans = new long[name];
      for (int in2 = 0; in2 < name; in2++)
        ans[in2] = nextLong();
      return ans;
    }
  }

