    int q = scan.nextInt();
    String strings = scan.next();
    int[][] questions = new int[q][2];
    for (int in2 = 0; in2 < q; in2++) questions[in2] = scan.nextIntArray(2);
    int[] ints = new int[name + 1];
    ints[0] = 0;
    ints[1] = 0;
    for (int in2 = 2; in2 <= name; in2++) {
      if(strings.substring(in2 - 2, in2).equals("AC")) ints[in2] = ints[in2 - 1] + 1;
