public class Main {
	public static int calc(int cost,int number) {
		while(true) {
			cost%=number;
			if(cost==0)return number;
			number%=cost;
			if(number==0)return cost;
		}
	}
	public static void main(String[] args) throws IOException{
		BufferedReader point=new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer eat=new StringTokenizer(point.readLine());
		int cost=Integer.parseInt(eat.nextToken()),number=Integer.parseInt(eat.nextToken()),currentT=Integer.parseInt(eat.nextToken());
		int currentX=calc(cost,number),ret=currentX;
		while(currentT>1) {
			if(currentX%--ret==0)--currentT;
		}
		System.out.println(ret);
	}
}

