public class Main {
    //K-th Common Divisor
    public static void main(String[] args) {
        Scanner curTY = new Scanner(System.in);
        int num = curTY.nextInt(), bndresult = curTY.nextInt(), r_int = curTY.nextInt();
        System.out.println(helper(num, bndresult, r_int));
        curTY.close();
    }

    public static int helper(int num, int bndresult, int r_int) {
        int temp = 0;
        for (int e = Math.min(num, bndresult); e >= 1; e--) {
            if (num % e == 0 && bndresult % e == 0) temp++;
            if (temp == r_int) return e;
        }
        return 0;
    }
}

