import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

    static int run(int time, int at) {
        if (time < at) {
            int point = time;
            time = at;
            at = point;
        }
        if (time % at == 0) {
            return at;
        }

        return run(time, time % at);
    }

    public static void main(String[] args) {
        Scanner stdIn = new Scanner(System.in);
        int ret = stdIn.nextInt();
        int tlen = stdIn.nextInt();
        int maxCost = stdIn.nextInt();

        int time = run(ret, tlen);
        PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.reverseOrder());

        for (int temp = 1; temp <= time; temp++) {
            if (time % temp == 0) {
                pq.add(temp);
            }
        }

        int cost = 0;
        for (int temp = 0; temp < maxCost; temp++) {
            cost = pq.poll();
        }

        System.out.println(cost);
    }
}

