public class Main {
	public static int nextLine(int bit[], int m) {
		int house[] = new int[bit.length];
		house[0] = 0;
		house[1] = Math.abs(bit[1] - bit[0]);
		for (int time = 2; time < bit.length; time++) {
			house[time] = Integer.MAX_VALUE;
			for (int calc = 1; calc <= m; calc++) {
				if (time - calc >= 0) {
					house[time] = Math.min(Math.abs(bit[time - calc] - bit[time]) + house[time - calc], house[time]);
				}
			}
		}
		return house[bit.length - 1];
	}

