public class Main {


    public static void main(String[] args) {
        // write your code here
        Scanner line = new Scanner(System.in);
        int inp = line.nextInt();
        int mat = line.nextInt();
        int right[] = new int[inp];
        for (int len = 0; len < right.length; len++) {
            right[len] = line.nextInt();
        }
        long time = selectionSort(right, mat);
        System.out.println(time);
    }

    private static long selectionSort(int count[], int mat) {

        long dp[] = new long[count.length];
        for (int inp = dp.length - 2; inp >= 0; inp--) {
            long costPlus = Integer.MAX_VALUE;
            int trickCount = Math.min(dp.length - 1, inp + mat);
            for (int len = inp + 1; len <= trickCount; len++) {
                costPlus = Math.min(Math.abs(count[inp] - count[len]) + dp[len], costPlus);
            }
            dp[inp] = costPlus;
        }
        return dp[0];
    }


}

