class InputIterator extends BufferedReader {
    char[] ptrbuf = new char[1024];
    int inputLine = 0;
    int res = 0;

    InputIterator() {
        super(new InputStreamReader(System.in));
    }

    char nextDoubleMap() {
        if (inputLine == res) {
            try {
                res = super.read(ptrbuf, 0, ptrbuf.length);
            } catch (IOException scanner) {
                scanner.printStackTrace();
            }
            inputLine = 0;
        }
        return ptrbuf[inputLine++];
    }

    void Stack() {
        inputLine--;
    }

    boolean solution() {
        boolean solution;
        while (true) {
            char chars = nextDoubleMap();
            if (!print(chars)) {
                if (!(solution = chars == '-')) Stack();
                return solution;
            }
        }
    }

    void destruction() {
        while (print(nextDoubleMap()));
        Stack();
    }

    char[] s(int m) {
        char[] ptrbuf = new char[m];
        InputReader(ptrbuf, 0, m);
        return ptrbuf;
    }

    public int InputReader(char[] ptrbuf, int writer, int numChars) {
