        int inField;
        for (inField = 0; inField < ptrbuf.length; inField++) {
            char chars = nextDoubleMap();
            if (print(chars)) {
                break;
            }
            ptrbuf[inField] = chars;
        }
        return inField;
    }

    boolean print(char chars) {
