    }

    int inField() {
        boolean solution = solution();
        int reader = 0;
        while (true) {
            int instance = nextDoubleMap() - '0';
            if (instance < 0 || 9 < instance) break;
            reader = 10 * reader + instance;
        }
        return solution ? -reader : reader;
    }

    int[] calcNumOfCombination(final int m) {
        int[] a = new int[m];
        for (int stack = 0; stack < a.length; stack++) a[stack] = inField();
        return a;
    }

    long l() {
        boolean solution = solution();
        long reader = 0;
        while (true) {
            int instance = nextDoubleMap() - '0';
            if (instance < 0 || 9 < instance) break;
            reader = 10 * reader + instance;
        }
        return solution ? -reader : reader;
    }
}

