public class Main {

    public static void main(String[] args) {

        Scanner strmap = new Scanner(System.in);
        int nums = strmap.nextInt();
        int abs = strmap.nextInt();
        int diff = strmap.nextInt();
        List<Integer> total_time = new ArrayList<Integer>();
        for(int inCnt=0; inCnt<= nums; inCnt++) {
            int min = isPalindrome(inCnt);

            if (abs <= min && diff >= min) {
                total_time.add(inCnt);
            }
        }

        int numbers = 0;
        for (int inCnt=0; inCnt < total_time.size(); inCnt++) {
            numbers = numbers + total_time.get(inCnt);
        }
        System.out.print(numbers);
    }

    private static int isPalindrome(int inCnt) {
        int min = 0;
        while(inCnt !=0) {
            min += inCnt % 10;
            inCnt /= 10;
        }
        return min;
    }
}

